"""
INFRAESTRUCTURA — caché, réplica de lectura, cola de trabajos (workers) y mantenimiento.

Módulo independiente: no importa app.py. app.py lo activa con
    rdb = infra.make_rdb(db, ensure_schema, connect_replica_or_None)
    infra.init_infra(app, db=db, migrations=MIGRATIONS, is_admin=is_admin_session)

  1. CACHÉ      Upstash Redis (REST) > Redis (REDIS_URL) > memoria. Claves con "versión": cualquier escritura
                del panel sube la versión y deja obsoleto todo lo cacheado, sin borrar clave por clave.
  2. RÉPLICA    rdb() = lecturas (réplica si hay DATABASE_REPLICA_URL; si falla, cae al primario).
                Las escrituras (INSERT/UPDATE/DELETE) SIEMPRE van por db() = nodo principal.
  3. COLA       Los correos y tareas pesadas se encolan en la tabla "jobs" (dentro de la misma transacción
                que el cambio, patrón outbox) y un worker los procesa en segundo plano con reintentos.
  4. MANTENIMIENTO  Limpieza de trabajos viejos y creación de particiones mensuales de pedidos.
Variables: REDIS_URL | UPSTASH_REDIS_REST_URL + UPSTASH_REDIS_REST_TOKEN, DATABASE_REPLICA_URL, CRON_SECRET,
QSTASH_TOKEN (opcional), JOBS_KICK (1/0), JOBS_INLINE (1 = ejecutar al instante, para pruebas), CACHE_DISABLED (1),
ORDERS_RETENTION_MONTHS (opcional: borra particiones de pedidos más viejas que N meses).
"""
import hashlib
import hmac
import json
import os
import threading
import time
import urllib.request
from contextlib import contextmanager
from datetime import datetime, timedelta, timezone

from flask import Response, g, has_request_context, jsonify, request

LOG = lambda m: print(f'[VIANE-INFRA] {m}')  # noqa: E731
UTC = timezone.utc


def utc(offset_seconds=0):
    """Hora UTC como texto ISO de formato fijo: se puede comparar como texto (run_at <= ahora)."""
    return (datetime.now(UTC) + timedelta(seconds=offset_seconds)).strftime('%Y-%m-%dT%H:%M:%S')


# ===========================================================================
# 1) CACHÉ
# ===========================================================================
class Cache:
    MAX_MEM = 2000

    def __init__(self):
        self.disabled = os.environ.get('CACHE_DISABLED') == '1'
        self._mem, self._lock, self._flight = {}, threading.Lock(), {}
        self._down_until = 0.0
        self.hits = self.misses = 0
        self._rest_url = os.environ.get('UPSTASH_REDIS_REST_URL', '').strip().rstrip('/')
        self._rest_tok = os.environ.get('UPSTASH_REDIS_REST_TOKEN', '').strip()
        self._redis = None
        url = os.environ.get('REDIS_URL', '').strip()
        if url and not (self._rest_url and self._rest_tok):
            try:
                import redis  # opcional: pip install redis
                self._redis = redis.Redis.from_url(url, socket_timeout=0.6, socket_connect_timeout=0.6, decode_responses=True)
            except Exception as exc:
                LOG(f'Redis no disponible, se usa memoria: {exc!r}')
        self.backend = 'upstash' if (self._rest_url and self._rest_tok) else ('redis' if self._redis else 'memoria')

    # ---- acceso remoto (si falla, se usa la memoria unos segundos y el sitio sigue igual) ----
    def _remote(self, *cmd):
        if self.backend == 'memoria' or time.time() < self._down_until:
            return None, False
        try:
            if self.backend == 'upstash':
                req = urllib.request.Request(self._rest_url, method='POST', data=json.dumps(list(cmd)).encode(),
                                             headers={'Authorization': 'Bearer ' + self._rest_tok, 'Content-Type': 'application/json'})
                with urllib.request.urlopen(req, timeout=0.8) as r:
                    return json.loads(r.read()).get('result'), True
            return self._redis.execute_command(*cmd), True
        except Exception as exc:
            self._down_until = time.time() + 10
            LOG(f'Caché remota caída, uso memoria 10 s: {type(exc).__name__}')
            return None, False

    # ---- memoria ----
    def _mget(self, key):
        with self._lock:
            hit = self._mem.get(key)
            if not hit:
                return None
            if hit[0] and hit[0] < time.time():
                self._mem.pop(key, None)
                return None
            return hit[1]

    def _mset(self, key, val, ttl):
        with self._lock:
            if len(self._mem) >= self.MAX_MEM:
                now = time.time()
                for k in [k for k, v in self._mem.items() if v[0] and v[0] < now] or list(self._mem)[: self.MAX_MEM // 4]:
                    self._mem.pop(k, None)
            self._mem[key] = ((time.time() + ttl) if ttl else 0, val)

    # ---- API ----
    def get(self, key):
        val, ok = self._remote('GET', key)
        return val if ok else self._mget(key)

    def set(self, key, val, ttl=60):
        _, ok = self._remote('SET', key, val, 'EX', int(ttl))
        if not ok:
            self._mset(key, val, ttl)

    def incr(self, key):
        val, ok = self._remote('INCR', key)
        if ok:
            return int(val)
        with self._lock:
            n = int((self._mem.get(key) or (0, 0))[1]) + 1
            self._mem[key] = (0, n)
            return n

    def version(self, ns):
        return str(self.get(f'viane:v:{ns}') or 0)

    def bump(self, ns='data'):
        """Deja obsoleto todo lo cacheado de ese espacio (se llama tras cada escritura del panel)."""
        return self.incr(f'viane:v:{ns}')

    def cached(self, ns, key, ttl, loader):
        """Devuelve el valor guardado o lo calcula UNA sola vez (aunque lleguen 100 visitas a la vez)."""
        if self.disabled:
            return loader()
        k = f'viane:{ns}:{self.version(ns)}:{key}'
        raw = self.get(k)
        if raw is not None:
            self.hits += 1
            return json.loads(raw)
        with self._lock:
            lock = self._flight.setdefault(k, threading.Lock())
        with lock:
            raw = self.get(k)
            if raw is not None:
                self.hits += 1
                return json.loads(raw)
            self.misses += 1
            val = loader()
            self.set(k, json.dumps(val, default=str, ensure_ascii=False), ttl)
        with self._lock:
            self._flight.pop(k, None)
        return val

    def stats(self):
        return {'backend': self.backend, 'aciertos': self.hits, 'fallos': self.misses, 'en_memoria': len(self._mem)}


cache = Cache()


def cached_json(ns, key, ttl, loader, s_maxage=20, swr=60):
    """Respuesta JSON cacheable: ETag (304 si no cambió) y caché de borde (CDN) corta con revalidación."""
    body = json.dumps(cache.cached(ns, key, ttl, loader), ensure_ascii=False, separators=(',', ':'), default=str)
    resp = Response(body, mimetype='application/json')
    resp.set_etag(hashlib.md5(body.encode('utf-8')).hexdigest())
    resp.headers['Cache-Control'] = f'public, max-age=0, s-maxage={s_maxage}, stale-while-revalidate={swr}'
    resp.headers['Vary'] = 'Cookie'  # quien tiene sesión (administración) siempre ve datos frescos
    return resp.make_conditional(request)


# ===========================================================================
# 2) RÉPLICA DE LECTURA
# ===========================================================================
def make_rdb(primary_db, ensure_schema, connect_replica=None):
    """rdb(): conexión de SOLO LECTURA (réplica). Sin réplica configurada, o si falla, usa el principal."""
    @contextmanager
    def rdb():
        con = None
        if connect_replica is not None:
            try:
                ensure_schema()
                con = connect_replica()
            except Exception as exc:
                LOG(f'Réplica no disponible, leo del principal: {type(exc).__name__}')
        if con is None:
            with primary_db() as c:
                yield c
            return
        try:
            yield con
        finally:
            try:
                con.rollback()  # solo lectura: no hay nada que confirmar
            except Exception:
                pass
            con.close()
    return rdb


# ===========================================================================
# 3) COLA DE TRABAJOS (outbox + workers)
# ===========================================================================
class PermanentJobError(Exception):
    """El trabajo no tiene sentido reintentarlo (p. ej. el correo no está configurado)."""


HANDLERS = {}
STALE_SECONDS = 600


def handler(kind):
    def deco(fn):
        HANDLERS[kind] = fn
        return fn
    return deco


def _inline():
    return os.environ.get('JOBS_INLINE') == '1'


def enqueue(c, kind, payload, delay=0, max_attempts=5):
    """Guarda el trabajo dentro de la MISMA transacción del cambio (si el cambio falla, el trabajo no existe).
    Devuelve 'en cola'. Con JOBS_INLINE=1 lo ejecuta al instante y devuelve su resultado (pruebas / desarrollo)."""
    if _inline():
        try:
            return HANDLERS[kind](payload)
        except Exception as exc:
            return 'error: ' + type(exc).__name__
    c.execute('INSERT INTO jobs(kind,payload,run_at,max_attempts,created_at) VALUES(%s,%s,%s,%s,%s)',
              (kind, json.dumps(payload, ensure_ascii=False), utc(delay), max_attempts, utc()))
    if has_request_context():
        g.jobs_pending = True
    return 'en cola'


def enqueue_mail(c, to, subject, text, notice=None):
    """Encola un correo. notice=[codigo_pedido, tipo] borra ese aviso si el envío falla del todo (para poder reintentar)."""
    return enqueue(c, 'email', {'to': to, 'subject': subject, 'text': text, 'notice': notice})


def send_email_now(to, subject, text):
    """Envío real: Resend si hay RESEND_API_KEY; si no, el SMTP del sitio. Devuelve (ok, estado)."""
    key = os.environ.get('RESEND_API_KEY', '').strip()
    if key:
        try:
            req = urllib.request.Request(
                'https://api.resend.com/emails', method='POST',
                data=json.dumps({'from': os.environ.get('RESEND_FROM') or 'VIANE DELICATESSEN <onboarding@resend.dev>',
                                 'to': [to], 'subject': subject, 'text': text}).encode('utf-8'),
                headers={'Authorization': 'Bearer ' + key, 'Content-Type': 'application/json'})
            with urllib.request.urlopen(req, timeout=15) as r:
                return (200 <= r.status < 300), ('enviado' if 200 <= r.status < 300 else f'error: HTTP {r.status}')
        except Exception as exc:
            return False, 'error: ' + type(exc).__name__
    import viane_extras as X
    if not X.smtp_configured():
        raise PermanentJobError('correo no configurado (SMTP_USER / SMTP_PASSWORD o RESEND_API_KEY)')
    return X.send_mail(to, subject, text)


@handler('email')
def _job_email(p):
    ok, status = send_email_now(p['to'], p['subject'], p['text'])
    if not ok:
        raise RuntimeError(status)
    return status


def _backoff(attempts):
    return min(30 * 2 ** (attempts - 1), 3600)  # 30 s, 1 min, 2 min, 4 min... máximo 1 hora


def run_jobs(db, limit=10, budget=20.0):
    """Reclama trabajos con FOR UPDATE SKIP LOCKED (varios workers a la vez sin pisarse), los ejecuta FUERA
    de la transacción y reintenta con espera creciente. Devuelve un resumen."""
    t0, out = time.time(), {'reclamados': 0, 'hechos': 0, 'reintentos': 0, 'fallidos': 0, 'omitidos': 0}
    with db() as c:
        c.execute("UPDATE jobs SET status='pending' WHERE status='running' AND locked_at < %s", (utc(-STALE_SECONDS),))
        claimed = c.execute(
            "UPDATE jobs SET status='running', locked_at=%s, attempts=attempts+1 WHERE id IN ("
            "SELECT id FROM jobs WHERE status='pending' AND run_at <= %s ORDER BY run_at, id LIMIT %s FOR UPDATE SKIP LOCKED) "
            'RETURNING id,kind,payload,attempts,max_attempts', (utc(), utc(), int(limit))).fetchall()
    out['reclamados'] = len(claimed)
    for j in claimed:
        if time.time() - t0 > budget:  # sin tiempo: lo devuelvo a la cola para el siguiente worker
            with db() as c:
                c.execute("UPDATE jobs SET status='pending', attempts=attempts-1, locked_at=NULL WHERE id=%s", (j['id'],))
            continue
        payload = {}
        try:
            payload = json.loads(j['payload'] or '{}')
            fn = HANDLERS.get(j['kind'])
            if not fn:
                raise PermanentJobError('tipo de trabajo desconocido: ' + str(j['kind']))
            res = fn(payload)
            with db() as c:  # al terminar se borra el contenido (puede llevar enlaces secretos)
                c.execute("UPDATE jobs SET status='done', done_at=%s, payload='{}', last_error=%s WHERE id=%s",
                          (utc(), str(res or '')[:200], j['id']))
            out['hechos'] += 1
        except PermanentJobError as exc:
            _release_notice(db, payload)
            with db() as c:
                c.execute("UPDATE jobs SET status='skipped', done_at=%s, payload='{}', last_error=%s WHERE id=%s",
                          (utc(), str(exc)[:200], j['id']))
            out['omitidos'] += 1
        except Exception as exc:
            final = j['attempts'] >= j['max_attempts']
            if final:
                _release_notice(db, payload)
            with db() as c:
                if final:
                    c.execute("UPDATE jobs SET status='failed', done_at=%s, last_error=%s WHERE id=%s",
                              (utc(), (type(exc).__name__ + ': ' + str(exc))[:200], j['id']))
                else:
                    c.execute("UPDATE jobs SET status='pending', locked_at=NULL, run_at=%s, last_error=%s WHERE id=%s",
                              (utc(_backoff(j['attempts'])), (type(exc).__name__ + ': ' + str(exc))[:200], j['id']))
            out['fallidos' if final else 'reintentos'] += 1
    return out


def _release_notice(db, payload):
    """Si un aviso de estado de pedido no pudo enviarse, se borra su marca para poder intentarlo de nuevo."""
    n = (payload or {}).get('notice')
    if n and len(n) == 2:
        try:
            with db() as c:
                c.execute('DELETE FROM order_notices WHERE order_code=%s AND kind=%s', (n[0], n[1]))
        except Exception:
            pass


_worker = {'t': None}


def kick(db):
    """Despierta al worker sin bloquear la respuesta: QStash (empuje HTTP) > hilo local > cron."""
    token = os.environ.get('QSTASH_TOKEN', '').strip()
    if token:
        try:
            dest = request.host_url.rstrip('/') + '/api/worker/run'
            req = urllib.request.Request('https://qstash.upstash.io/v2/publish/' + dest, method='POST', data=b'{}',
                                         headers={'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json',
                                                  'Upstash-Forward-Authorization': 'Bearer ' + os.environ.get('CRON_SECRET', ''),
                                                  'Upstash-Retries': '2'})
            urllib.request.urlopen(req, timeout=2).close()
            return 'qstash'
        except Exception as exc:
            LOG(f'QStash no respondió: {type(exc).__name__}')
    if os.environ.get('JOBS_KICK', '0' if os.environ.get('VERCEL') else '1') == '1':
        t = _worker['t']
        if not (t and t.is_alive()):
            _worker['t'] = threading.Thread(target=lambda: _safe(run_jobs, db, 5, 15), daemon=True)
            _worker['t'].start()
        return 'hilo'
    return 'cron'


def _safe(fn, *a):
    try:
        return fn(*a)
    except Exception as exc:
        LOG(f'worker: {type(exc).__name__}: {exc}')


# ===========================================================================
# 4) MANTENIMIENTO (particiones, limpieza)
# ===========================================================================
def run_maintenance(db):
    """Limpia trabajos, enlaces y sesiones vencidos y crea las particiones mensuales de pedidos (si están instaladas)."""
    out = {}
    with db() as c:
        def opcional(label, sql, params, campo=None):
            c.execute('SAVEPOINT m')  # si la tabla/función aún no existe, se omite sin romper lo demás
            try:
                cur = c.execute(sql, params)
                out[label] = cur.fetchone()[campo] if campo else cur.rowcount
                c.execute('RELEASE SAVEPOINT m')
            except Exception:
                c.execute('ROLLBACK TO SAVEPOINT m')
                out[label] = 'no instalado'
        opcional('trabajos_borrados', "DELETE FROM jobs WHERE status IN ('done','failed','skipped') AND created_at < %s", (utc(-30 * 86400),))
        opcional('enlaces_vencidos_borrados', 'DELETE FROM affiliate_invites WHERE created_at < %s', (utc(-60 * 86400),))
        opcional('sesiones_vencidas_borradas', 'DELETE FROM affiliate_sessions WHERE expires_at < %s', (utc(-86400),))
        opcional('particiones_creadas', 'SELECT viane_ensure_order_partitions(%s) AS n', (3,), 'n')
        if _retention():
            opcional('particiones_borradas', 'SELECT viane_drop_old_partitions(%s) AS n', (_retention(),), 'n')
    return out


def _retention():
    try:
        return int(os.environ.get('ORDERS_RETENTION_MONTHS') or 0)
    except ValueError:
        return 0


