# DDL: cola e índices (también está en supabase_arquitectura.sql)
# ===========================================================================
JOBS_DDL = [
    '''CREATE TABLE IF NOT EXISTS jobs(
        id BIGSERIAL PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL DEFAULT '{}',
        status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0,
        max_attempts INTEGER NOT NULL DEFAULT 5, run_at TEXT NOT NULL, locked_at TEXT, done_at TEXT,
        last_error TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL)''',
    "CREATE INDEX IF NOT EXISTS idx_jobs_due ON jobs(run_at, id) WHERE status = 'pending'",
    "CREATE INDEX IF NOT EXISTS idx_jobs_running ON jobs(locked_at) WHERE status = 'running'",
    "CREATE INDEX IF NOT EXISTS idx_jobs_cleanup ON jobs(created_at) WHERE status IN ('done','failed','skipped')",
    'ALTER TABLE jobs ENABLE ROW LEVEL SECURITY',
]
INDEX_DDL = [
    # pedidos: estado, pago, fechas, vendedor, teléfono (búsquedas y paneles)
    'CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status)',
    'CREATE INDEX IF NOT EXISTS idx_orders_payment ON orders(payment_status)',
    'CREATE INDEX IF NOT EXISTS idx_orders_created ON orders(created_at DESC)',
    'CREATE INDEX IF NOT EXISTS idx_orders_reseller ON orders(reseller_id) WHERE reseller_id IS NOT NULL',
    'CREATE INDEX IF NOT EXISTS idx_orders_phone ON orders(phone)',
    'CREATE INDEX IF NOT EXISTS idx_orders_delivery ON orders(delivery_date)',
    # ventas: reportes por día/mes, papelera, unión con pedidos
    'CREATE INDEX IF NOT EXISTS idx_sales_date ON sales(sold_date DESC) WHERE deleted_at IS NULL',
    'CREATE INDEX IF NOT EXISTS idx_sales_month ON sales((LEFT(sold_date, 7))) WHERE deleted_at IS NULL',
    'CREATE INDEX IF NOT EXISTS idx_sales_trash ON sales(deleted_at) WHERE deleted_at IS NOT NULL',
    # catálogo y reseñas (lo que carga cada visita)
    'CREATE INDEX IF NOT EXISTS idx_products_active ON products(active, category, id DESC)',
    'CREATE INDEX IF NOT EXISTS idx_reviews_approved ON reviews(approved, id DESC)',
    'CREATE INDEX IF NOT EXISTS idx_ads_active ON ads(active, id)',
    'CREATE INDEX IF NOT EXISTS idx_payments_active ON payments(active, id)',
    'CREATE INDEX IF NOT EXISTS idx_resellers_active ON resellers(active)',
    # afiliados
    'CREATE INDEX IF NOT EXISTS idx_affiliates_lower_email ON affiliates((LOWER(email)))',
    'CREATE INDEX IF NOT EXISTS idx_affiliates_reseller ON affiliates(reseller_id) WHERE reseller_id IS NOT NULL',
    'CREATE INDEX IF NOT EXISTS idx_affiliates_created ON affiliates(created_at DESC)',
    'CREATE INDEX IF NOT EXISTS idx_templates_active ON affiliate_templates(active, sort, id)',
    'CREATE INDEX IF NOT EXISTS idx_users_role ON users(role, is_active)',
]


# ===========================================================================
# Registro en la aplicación Flask
# ===========================================================================
def init_infra(app, db, migrations, is_admin):
    for stmt in JOBS_DDL + INDEX_DDL:
        if stmt not in migrations:
            migrations.append(stmt)
    app.config.setdefault('PUBLIC_CACHE', set()).update({'/api/public', '/api/store/legal'})

    def authorized():
        secret = os.environ.get('CRON_SECRET', '').strip()
        auth = request.headers.get('Authorization', '')
        return bool(secret and hmac.compare_digest(auth.encode(), ('Bearer ' + secret).encode())) or is_admin()

    @app.route('/api/worker/run', methods=['GET', 'POST'])
    def worker_run():
        """Lo llaman: QStash tras encolar, Vercel Cron cada minuto, o un administrador."""
        if not authorized():
            return jsonify({'error': 'No autorizado'}), 401
        return jsonify({'ok': True, **run_jobs(db, limit=int(request.args.get('limit', 20) or 20), budget=25.0)})

    @app.route('/api/maintenance/run', methods=['GET', 'POST'])
    def maintenance_run():
        """Cron diario: limpieza + particiones del mes siguiente."""
        if not authorized():
            return jsonify({'error': 'No autorizado'}), 401
        return jsonify({'ok': True, **run_maintenance(db), 'cache': cache.stats()})

    SKIP_EXACT = {('POST', '/api/orders'), ('POST', '/api/reviews'), ('POST', '/api/login'), ('POST', '/api/logout'),
                  ('POST', '/api/resellers/validate'), ('POST', '/api/affiliates')}
    SKIP_PREFIX = ('/api/paypal/', '/api/worker', '/api/maintenance', '/afiliados/api/login', '/afiliados/api/logout',
                   '/afiliados/api/registro', '/afiliados/api/recuperar', '/afiliados/api/activar', '/afiliados/api/retiro',
                   '/afiliados/api/avatar', '/afiliados/api/cron', '/api/upload')

    @app.after_request
    def infra_after(resp):
        if (request.method in ('POST', 'PUT', 'PATCH', 'DELETE') and resp.status_code < 400
                and request.path.startswith(('/api/', '/afiliados/api/'))
                and (request.method, request.path) not in SKIP_EXACT and not request.path.startswith(SKIP_PREFIX)):
            cache.bump('data')  # cualquier cambio del panel deja obsoleta la caché de lectura
        if g.get('jobs_pending'):
            _safe(kick, db)
        return resp
